return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-08T20:36:54+00:00','po-revision-date'=>'2026-09-08T20:36:54+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Za stranice smještene na usluzi Zinn Digital®. Upravlja predmemorijom stranica koju vaš Zinn® poslužitelj već osigurava — pametno automatsko čišćenje pri promjeni sadržaja, udaljeno čišćenje s vaše Zinn® upravljačke ploče, prekidač za Redis objektnu predmemoriju, sigurna WordPress/WooCommerce izuzeća i administrativna prijava jednim klikom. Ovo je upravitelj predmemorije, a ne mehanizam predmemorije. Hostate negdje drugdje? Umjesto toga instalirajte Zinn® Cache Engine.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Cache'=>'Predmemorija','Page cache'=>'Predmemorija stranice','Object cache'=>'Predmemorija objekta','Purging'=>'Čišćenje','Exclusions'=>'Isključenja','Purge everything now'=>'Očisti sve odmah','Every cached page is discarded and will be rebuilt as visitors arrive. Continue?'=>'Svaka spremljena stranica bit će odbačena i ponovno izrađena kako posjetitelji budu dolazili. Želite li nastaviti?','Full-page cache'=>'Predmemorija cijele stranice','Served by LiteSpeed at the web server, before WordPress runs. This is where nearly all the speed comes from.'=>'Poslužuje LiteSpeed na web-poslužitelju, prije nego što WordPress se pokrene. Odatle dolazi gotovo sva brzina.','Send LiteSpeed cache-control and tag headers on cacheable pages'=>'Pošaljite LiteSpeed zaglavlja za upravljanje predmemorijom i oznake na stranicama koje se mogu predmemorirati','How long a page stays cached'=>'Koliko dugo stranica ostaje u predmemoriji','Seconds. A week suits most sites; a news site publishing hourly wants far less.'=>'Sekunde. Tjedan dana odgovara većini web-mjesta; vijestima koje objavljuju svakog sata potrebno je znatno manje.','How long a visitor’s browser keeps images and scripts'=>'Koliko dugo posjetiteljev preglednik čuva slike i skripte','Seconds. Applies to images, CSS and JavaScript only — never to pages. Set to 0 to leave this to your host.'=>'Sekunde. Odnosi se samo na slike, CSS i JavaScript — nikada na stranice. Postavite na 0 da biste to prepustili svom pružatelju hostinga.','Signed-in visitors'=>'Prijavljeni posjetitelji','Never serve a cached page to a signed-in visitor'=>'Nikada ne poslužujte predmemoriranu stranicu prijavljenom posjetitelju','On is the safe answer and the default. Turn it off only if you know every cached page is identical for every signed-in user — a membership site is the usual reason not to.'=>'Uključeno je siguran odgovor i zadana postavka. Isključite ga samo ako znate da je svaka spremljena stranica potpuno identična za svakog prijavljenog korisnika – članske stranice uobičajeni su razlog za to.','Different lifetimes for different content'=>'Različiti životni vijek za različite sadržaje','For example: a shop’s product pages for an hour, while everything else stays a week.'=>'Na primjer: stranice s proizvodima trgovine na sat vremena, dok sve ostalo ostaje tjedan dana.','Add a rule'=>'Dodaj pravilo','Content type'=>'Vrsta sadržaja','Seconds'=>'Sekunde','Object cache (Redis)'=>'Objektna predmemorija (Redis)','Caches the results of database queries. It helps most on a busy shop or a site with a lot of signed-in traffic, where the page cache cannot.'=>'Pohranjuje rezultate upita baze podataka u predmemoriju. Najviše pomaže u prometnoj trgovini ili na web-mjestu s puno prijavljenog prometa, gdje predmemorija stranice ne može pomoći.','Install the Redis object-cache drop-in'=>'Instalirajte Redis dodatak za predmemoriju objekata','Needs the phpredis extension. If it is missing, the box above this screen says so.'=>'Potrebna je phpredis ekstenzija. Ako nedostaje, okvir iznad ovog zaslona to prikazuje.','Redis host'=>'Redis poslužitelj (host)','Redis port'=>'Redis priključak (port)','Redis database'=>'Redis baza podataka','Give each site on a shared Redis its own number, or they will clear each other’s cache.'=>'Dodijelite svakoj stranici na zajedničkom Redis vlastiti broj kako ne bi međusobno brisale predmemoriju.','Redis password'=>'Redis lozinka','Leave blank if your Redis does not need one.'=>'Ostavite prazno ako vaš Redis nije potreban.','Key prefix'=>'Prefiks ključa','An alternative to a separate database number when you cannot have one.'=>'Alternativa zasebnom broju baze podataka kada ga ne možete imati.','Smart auto-purge'=>'Pametno automatsko čišćenje','Clear affected pages automatically when content changes'=>'Automatski očisti zahvaćene stranice kada se sadržaj promijeni','After updates'=>'Nakon ažuriranja','Clear everything after a core, plugin or theme update'=>'Očistite sve nakon ažuriranja jezgre, dodatka ili teme','After a comment'=>'Nakon komentara','Clear a post’s page when a comment on it is approved'=>'Očistite stranicu objave kada je komentar na nju odobren','Turn this off on a very busy comment section, where it can clear the same page hundreds of times an hour.'=>'Isključite ovo u odjeljku s komentarima koji je vrlo posjećen, gdje se ista stranica može očistiti stotine puta na sat.','Never cache these'=>'Nikad ne predmemoriraj ove','Sensible WordPress and WooCommerce defaults are always applied — cart, checkout, my-account and any signed-in session are never cached, whatever is below.'=>'Razumne zadane postavke za WordPress i WooCommerce uvijek se primjenjuju – košarica, naplata, moj-račun i svaka prijavljena sesija nikada se ne predmemoriraju, bez obzira na sve što je ispod.','Addresses'=>'Adrese','One path per line, for example <code>/basket</code>. A trailing <code>*</code> matches everything under it.'=>'Jedna staza po retku, na primjer <code>/basket</code>. Vodeća <code>*</code> podudara se sa svemu ispod nje.','Query parameters'=>'Parametri upita','A page carrying one of these is never cached — for example a one-time preview token.'=>'Stranica koja sadrži jednu od ovih nikada se ne predmemorira – na primjer, jednokratni token za pretpregled.','Cookies'=>'Kolačići','A visitor carrying one of these is always served a fresh page.'=>'Posjetitelju koji nosi jedan od ovih uvijek se poslužuje svježa stranica.','Every cached page has been discarded. They will be rebuilt as visitors arrive.'=>'Svaka predmemorirana stranica je uklonjena. Bit će ponovno izrađene kako posjetitelji budu dolazili.','The page cache is on, but this server is not LiteSpeed.'=>'Predmemorija stranice je uključena, ali ovaj poslužitelj nije LiteSpeed.','The cache headers are being sent and nothing is reading them, so pages are not actually being cached. Ask your host whether LiteSpeed is available, or move to Zinn® hosting where it is standard.'=>'Zaglavlja predmemorije se šalju, ali ih nitko ne čita, tako da se stranice zapravo ne predmemoriraju. Upitajte svog pružatelja usluga je li LiteSpeed dostupan ili pređite na Zinn® hosting gdje je on standardan.','The object cache is on, but this server has no Redis support.'=>'Predmemorija objekata je uključena, ali ovaj poslužitelj nema podršku za Redis.','The phpredis extension is not installed, so the drop-in cannot be used and WordPress is falling back to its own in-memory cache. Ask your host to enable phpredis.'=>'Proširenje phpredis nije instalirano, pa se dodatak ne može koristiti i WordPress se vraća na vlastitu predmemoriju u memoriji. Zatražite od svog pružatelja usluga udomljavanja da omogući phpredis.','Nothing is being cached.'=>'Ništa se ne predmemorira.','Both caches are switched off, so this plugin is not making the site any faster.'=>'Oba su predmemoriranja isključena, tako da ovaj dodatak ne ubrzava web-mjesto.','Caching is active on this site.'=>'Predmemoriranje je aktivno na ovoj web-lokaciji.','Web server'=>'Web-poslužitelj','LiteSpeed — page caching available'=>'LiteSpeed — dostupno predmemoriranje stranica','not LiteSpeed — page caching unavailable'=>'nije LiteSpeed — predmemoriranje stranica nije dostupno','Redis support'=>'Podrška za Redis','phpredis is installed'=>'phpredis je instaliran','phpredis is not installed'=>'phpredis nije instaliran','Page lifetime'=>'Vijek stranice','You are not allowed to purge the cache.'=>'Nemate dopuštenje za čišćenje predmemorije.','Cache purge requested.'=>'Zatraženo je čišćenje predmemorije.','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® Cache: instaliran je drugi dodatak za predmemoriju objekata, tako da Redis predmemorijom objekata ne upravlja ovaj dodatak.','detected'=>'otkriveno','not detected'=>'nije otkriveno','phpredis extension missing'=>'nedostaje phpredis ekstenzija','active'=>'aktivno','inactive'=>'neaktivno','LiteSpeed cache:'=>'LiteSpeed predmemorija:','Redis object cache:'=>'Redis objektna predmemorija:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'Redis PHP ekstenzija (phpredis) nije dostupna na ovom poslužitelju, pa se objektna predmemorija ne može omogućiti.','Another object-cache drop-in is already installed. Remove it before enabling the Zinn® object cache.'=>'Još jedan dodatak za predmemoriju objekata (object-cache) već je instaliran. Uklonite ga prije nego što omogućite Zinn® predmemoriju objekata.','Could not write the Redis connection configuration file.'=>'Nije bilo moguće zapisati konfiguracijsku datoteku Redis veze.','The bundled object-cache drop-in could not be read.'=>'Priloženi object-cache drop-in nije bilo moguće pročitati.','Could not install the object-cache drop-in into wp-content.'=>'Nije bilo moguće instalirati object-cache drop-in u wp-content.','Could not remove the object-cache drop-in.'=>'Nije bilo moguće ukloniti object-cache drop-in.','The WordPress filesystem is not writable, so the object-cache drop-in could not be managed.'=>'WordPress datotečni sustav nije zapisiv, pa object-cache drop-in nije bilo moguće postaviti.','This one-click login link is not valid any more. Links expire after a couple of minutes and can only be used once — open your site from the Zinn® dashboard again to get a fresh one.'=>'Ova poveznica za prijavu jednim klikom više nije važeća. Poveznice istječu nakon nekoliko minuta i mogu se upotrijebiti samo jednom — otvorite svoju web-lokaciju ponovno s upravljačke ploče sustava Zinn® kako biste dobili novu.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju za Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta te nije instalirano.','Stored. Type a new value to replace it.'=>'Pohranjeno. Unesite novu vrijednost da biste je zamijenili.','Filter this list…'=>'Filtriraj ovaj popis…','Filter this list'=>'Filtriraj ovaj popis','Nothing matches that filter.'=>'Nijedna stavka ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Ukloni ovaj red','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® – pregled','Overview'=>'Pregled','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® dodatak na ovoj stranici i status njegovog rada.','No connection is needed for this plugin.'=>'Za ovaj dodatak nije potrebna nikakva veza.','Open settings'=>'Otvorite postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća svaku postavku ovog dodatka na zadane vrijednosti. Nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezi datoteku s postavkama','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokene ili API ključeve – morat ćete ih ponovno unijeti na novoj web-lokaciji.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke ovog dodatka vraćene su na zadane vrijednosti.','Done.'=>'Gotovo.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Ta se datoteka nije mogla pročitati. Odaberite datoteku postavki izvezenu iz Zinn® dodatka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz Zinn® postavki.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog dodatka (%s), pa bi njen uvoz ovdje pohranio postavke koje ovaj dodatak ne prepoznaje.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Uvođena je %d postavka. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih unesite ponovno.','Connected'=>'Povezano','Connecting…'=>'Spajanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pažnju','Not connected'=>'Nije povezano','Running on your own account'=>'Radi na vašem računu','We could not check this'=>'Nismo mogli ovo provjeriti','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Posljednja provjera prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo Zinn® podršci','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'To je točno ono što će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu u tome.','The diagnostics report that will be sent'=>'Dijagnostičko izvješće koje će biti poslano','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće Zinn® podršci','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvorit ćemo vam zahtjev za podršku i odgovoriti putem e-pošte. Ako ga radije ne biste poslali, kopirajte ga iznad i sami ga zalijepite u zahtjev.','Copied'=>'Kopirano','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo mogli kontaktirati Zinn Digital® s ovog poslužitelja (%s). Umjesto toga kopirajte gornje izvješće i otvorite zahtjev — s vašim postavkama nije ništa u redu.','Sent. Zinn® support has your report and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće i odgovorit će vam putem e-pošte.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće – referenca %s – i odgovorit će vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izvješća u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno – ona prethodna su stigla.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutno nije mogao prihvatiti izvještaj — to je problem na našoj strani, a ne vašoj. Pokušajte ponovo uskoro ili kopirajte gornji izvještaj u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvješće je odbijeno (HTTP %d). Kopirajte ga gore i otvorite zahtjev uz navođenje tog broja.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje vode više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude koji se time bave za život','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','Style preset'=>'Predefinedjeni stil','A starting point. Anything below overrides it.'=>'Polazna točka. Sve ispod toga ima prednost.','Use my own colours and sizes'=>'Upotrijebi moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Ostavite ovo isključeno i unaprijed postavljena vrijednost koristit će se točno takva kakva jest.']];